<h1>موضوعات و مسائل</h1><section class="card"><?= $this->start('/taxonomy/save') ?><?= $this->field('title','عنوان') ?><label>نوع<select name="kind"><option value="topic">موضوع</option><option value="issue">مسئله</option></select></label><label>موضوع بالادست مسئله<select name="parent_id"><option value="">بدون بالادست</option><?php foreach($rows as $r): if($r['kind']==='topic'&&$r['active']): ?><option value="<?= $this->h($r['id']) ?>"><?= $this->h($r['title']) ?></option><?php endif;endforeach; ?></select></label><button>افزودن</button></form></section>
<?php foreach($rows as $r): ?><section class="card section"><?= $this->start('/taxonomy/save') ?><input type="hidden" name="id" value="<?= $this->h($r['id']) ?>"><input type="hidden" name="kind" value="<?= $this->status($r['kind']) ?>"><input type="hidden" name="parent_id" value="<?= $this->h($r['parent_id']) ?>"><?= $this->field('title',$r['kind']==='topic'?'موضوع':'مسئله','text',$r['title']) ?><p><?= $this->h($r['parent_title']) ?></p><label>وضعیت<select name="active"><option value="1" <?= $r['active']?'selected':'' ?>>فعال</option><option value="0" <?= !$r['active']?'selected':'' ?>>غیرفعال</option></select></label><button class="secondary">ذخیره</button></form></section><?php endforeach; ?>
